BEGIN;
CREATE TABLE IF NOT EXISTS pooling.composition_snapshot(pool_id text NOT NULL REFERENCES pooling.pool(pool_id),business_date date NOT NULL,currency_code text NOT NULL,total_resources numeric(30,12) NOT NULL,bank_equity numeric(30,12) NOT NULL,iah_restricted numeric(30,12) NOT NULL,iah_unrestricted numeric(30,12) NOT NULL,invested_amount numeric(30,12) NOT NULL,uninvested_liquidity numeric(30,12) NOT NULL,maturity_gaps jsonb NOT NULL,currency_gaps jsonb NOT NULL,run_id uuid REFERENCES calculation.run(run_id),certified boolean NOT NULL,checksum_sha256 text NOT NULL CHECK(checksum_sha256~'^[a-f0-9]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(pool_id,business_date),FOREIGN KEY(pool_id,currency_code)REFERENCES pooling.pool(pool_id,currency_code),CHECK(total_resources=bank_equity+iah_restricted+iah_unrestricted),CHECK(uninvested_liquidity=total_resources-invested_amount),CHECK(invested_amount<=total_resources),CHECK((certified AND run_id IS NOT NULL)OR(NOT certified AND run_id IS NULL)));
CREATE OR REPLACE FUNCTION pooling.guard_composition_snapshot()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='DELETE' OR OLD.certified THEN RAISE EXCEPTION 'Certified pool composition is immutable and history cannot be purged';END IF;RETURN NEW;END;$$;DROP TRIGGER IF EXISTS composition_snapshot_guard ON pooling.composition_snapshot;CREATE TRIGGER composition_snapshot_guard BEFORE UPDATE OR DELETE ON pooling.composition_snapshot FOR EACH ROW EXECUTE FUNCTION pooling.guard_composition_snapshot();
COMMIT;
